<template><div class="page"><div class="intro"><div><span class="eyebrow">AD PLAN CENTER</span><h1>广告计划中心</h1><p>导入 TikTok 导出的广告数据快照，查看需要人工回后台确认的计划。</p></div><label class="upload-button">导入 Excel<input type="file" accept=".xlsx,.xlsm,.csv" @change="importFile"/></label></div><div v-if="importMessage" class="import-message">{{ importMessage }}</div><div class="ops-grid"><section class="workspace-panel"><div class="section-head"><h3>当前广告计划</h3><el-button link @click="load">刷新</el-button></div><el-table :data="plans" stripe empty-text="暂无广告计划"><el-table-column prop="plan_name" label="广告计划" min-width="220"/><el-table-column prop="current_status" label="状态"/><el-table-column prop="strategy_code" label="策略" width="80"/><el-table-column prop="target_roi" label="目标 ROI" width="100"/><el-table-column label="操作" width="90"><template #default="scope"><el-button link @click="showSnapshots(scope.row)">快照</el-button></template></el-table-column></el-table></section><section class="workspace-panel"><div class="section-head"><h3>最近导入</h3><el-link @click="router.push('/operations')">运营记录</el-link></div><div v-for="batch in batches.slice(0,6)" :key="batch.id" class="home-link-row"><span>{{ batch.file_name }}</span><small>{{ batch.row_count }} 行 · {{ batch.status }}</small></div><el-empty v-if="!batches.length" description="暂无导入批次" :image-size="50"/></section></div><section class="workspace-panel"><div class="section-head"><h3>广告策略</h3><span class="muted">目标 ROI 由产品策略提供</span></div><el-table :data="strategies" stripe empty-text="暂无策略配置"><el-table-column prop="product_id" label="产品 ID" width="90"/><el-table-column prop="strategy_code" label="策略" width="80"/><el-table-column prop="base_target_roi" label="基础目标 ROI"/><el-table-column prop="multiplier" label="系数"/><el-table-column prop="enabled" label="启用"/></el-table></section><section v-if="selectedPlan" class="workspace-panel"><div class="section-head"><h3>{{ selectedPlan.plan_name }} 的历史快照</h3><el-button link @click="selectedPlan=null">关闭</el-button></div><el-table :data="snapshots" stripe empty-text="暂无快照"><el-table-column prop="snapshot_at" label="时间"/><el-table-column prop="spend" label="消耗"/><el-table-column prop="orders" label="订单"/><el-table-column prop="actual_roi" label="实际 ROI"/><el-table-column prop="reason" label="判断"/><el-table-column prop="recommendation" label="建议"/></el-table></section></div></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import axios from 'axios'; import { ElMessage } from 'element-plus'; const plans=ref<any[]>([]),batches=ref<any[]>([]),snapshots=ref<any[]>([]),strategies=ref<any[]>([]),selectedPlan=ref<any>(null),importMessage=ref(''); async function load(){[plans.value,batches.value,strategies.value]=await Promise.all([(await axios.get('/api/ads/plans')).data,(await axios.get('/api/ads/import-batches')).data,(await axios.get('/api/ad-strategies')).data]);} async function importFile(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const data=new FormData();data.append('file',file);try{const result=(await axios.post('/api/ads/import',data)).data;importMessage.value=`已导入 ${result.batch.row_count} 行，生成 ${result.snapshots} 条快照`;ElMessage.success('广告数据导入成功');await load();}catch(error:any){ElMessage.error(error?.response?.data?.detail||'导入失败');}} async function showSnapshots(plan:any){selectedPlan.value=plan;snapshots.value=(await axios.get('/api/ads/snapshots',{params:{ad_plan_id:plan.id}})).data;} onMounted(load);</script>
